@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_227b68aed0c24432bd0e1beef2672088.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<p>
    Sort by:
    <button class="btn btn-sm @(Sort != "popular" ? "btn-primary" : "btn-outline-primary")" @onclick='() => SetSort("newest")'>Newest</button>
    <button class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")" @onclick='() => SetSort("popular")'>Popular</button>
</p>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in GetSortedRecipes())
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _error;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        var cts = _loadCts;

        _error = null;
        _isRefreshing = _recipes is not null;
        var targetCuisineId = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(targetCuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _loadedCuisineId = targetCuisineId;
            _isRefreshing = false;
            _error = null;
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation away or new cuisine selected) — ignore
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", targetCuisineId);
            _isRefreshing = false;
            _error = "Something went wrong loading recipes. Please try again.";
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new();

        return Sort == "popular"
            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private void SetSort(string sort)
    {
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={sort}");
    }

    private async Task Retry()
    {
        _error = null;
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

